#!/usr/bin/env bash
# Compile and upload the beacon firmware. Reads Wi-Fi credentials from esp32/.env.
# Usage: ./flash.sh [serial-port]   (auto-detects a USB serial port if omitted)
set -euo pipefail
cd "$(dirname "$0")"

[ -f .env ] || { echo "Missing esp32/.env (copy .env.example)"; exit 1; }
set -a; source .env; set +a

cat > beacon/secrets.h <<EOF
// Generated by flash.sh from .env. Do not commit.
#define WIFI_SSID "${WIFI_SSID}"
#define WIFI_PASS "${WIFI_PASS}"
EOF

PORT="${1:-$(ls /dev/cu.usbserial-* /dev/cu.wchusbserial* /dev/cu.SLAB_USBtoUART* 2>/dev/null | head -1 || true)}"
[ -n "$PORT" ] || { echo "No ESP32 serial port found"; exit 1; }

FQBN=esp32:esp32:esp32:UploadSpeed=115200  # 921600 is unreliable on this board
arduino-cli compile --fqbn "$FQBN" beacon
arduino-cli upload --fqbn "$FQBN" -p "$PORT" beacon
echo "Flashed $PORT. The LED should be solid on."
